const defaultState = () => ({
  identity:{teamName:'Unión Viera Alevín D',primary:'#0b5b49',secondary:'#17211d',accent:'#c3a654',crest:''},
  objectives:[], positionTrials:[], evaluations:[], postMatches:[], planning:[], diary:[], rivals:[], sessionDraft:[],
});
let state = loadState();
