function loadState(){
  try { return {...defaultState(), ...JSON.parse(localStorage.getItem(STORAGE_KEY) || '{}')}; } catch { return defaultState(); }
}
function saveState(){ localStorage.setItem(STORAGE_KEY, JSON.stringify(state)); renderDashboard(); }
function options(items, selected = ''){ return items.map(x => `<option value="${esc(x)}" ${x===selected?'selected':''}>${esc(x)}</option>`).join(''); }
function playerOptions(selected=''){ return PLAYERS.map(p=>`<option value="${esc(p.id)}" ${p.id===selected?'selected':''}>#${esc(p.number)} · ${esc(p.name)}</option>`).join(''); }
function matchOptions(){ return MATCHES.map(m=>`<option value="${m.id}">${esc(m.opponent)} · ${m.date.slice(0,10).split('-').reverse().join('/')} · ${m.type}</option>`).join(''); }
function formatDate(v){ if(!v)return '—'; const [y,m,d]=v.slice(0,10).split('-'); return `${d}/${m}/${y}`; }
function playerName(id){ return PLAYERS.find(p=>p.id===id)?.name || 'Jugador'; }
function playerById(id){ return PLAYERS.find(p=>p.id===id); }

function createSection(id,title,subtitle=''){
  const main=$('#app'); const section=document.createElement('section');
  section.id=id; section.className='view';
  section.innerHTML=`<div class="section-head"><div><p class="eyebrow">FútbolControl Beta</p><h2>${esc(title)}</h2>${subtitle?`<p class="meta">${esc(subtitle)}</p>`:''}</div><span class="fc-beta-badge">LAB AISLADO</span></div><div class="fc-root"></div>`;
  main.insertBefore(section, main.firstElementChild); return section.querySelector('.fc-root');
}
function addNav(id,label){
  const nav=$('.bottom-nav'); const b=document.createElement('button'); b.type='button'; b.dataset.view=id; b.className='fc-nav-new'; b.textContent=label; nav.insertBefore(b, nav.firstChild);
  b.addEventListener('click',()=>{ $$('.view').forEach(v=>v.classList.toggle('active',v.id===id)); $$('.bottom-nav button').forEach(x=>x.classList.toggle('active',x===b)); $('#app')?.focus(); });
}
function bindSubnav(root){
  root.addEventListener('click',e=>{ const b=e.target.closest('[data-fc-pane]'); if(!b)return; const pane=b.dataset.fcPane; $$('.fc-subnav button',root).forEach(x=>x.classList.toggle('active',x===b)); $$('.fc-pane',root).forEach(x=>x.classList.toggle('active',x.dataset.pane===pane)); });
}

function setupBrand(){
  document.title='FútbolControl · Laboratorio';
  const brand=$('.topbar-brand'); if(brand){ const img=$('img',brand); if(img){img.src='lab/futbolcontrol-logo.svg';img.alt='FútbolControl';} const h=$('h1',brand);if(h)h.textContent='FútbolControl'; const e=$('.eyebrow',brand);if(e)e.textContent='Gestión integral de fútbol'; }
  const net=$('#network-label'); if(net){net.textContent='LAB · Solo local';net.title='No hay conexión con Supabase real.';}
  const role=$('#role-label'); if(role)role.textContent='Entrenador · LAB';
  $('#logout')?.remove();
  document.body.classList.remove('auth-locked'); try{ if($('#auth-dialog')?.open) $('#auth-dialog').close(); }catch{}
  if(!$('.fc-lab-ribbon')) $('.topbar')?.insertAdjacentHTML('afterend','<div class="fc-lab-ribbon">FÚTBOLCONTROL BETA · copia completa aislada · guardado solo en este navegador</div>');
  applyIdentity();
}
function applyIdentity(){
  const i=state.identity; document.documentElement.style.setProperty('--fc-primary',i.primary); document.documentElement.style.setProperty('--fc-secondary',i.secondary); document.documentElement.style.setProperty('--fc-accent',i.accent);
  const top=$('.topbar'); if(top) top.style.background=i.primary;
  $$('.primary').forEach(b=>{b.style.background=i.primary;b.style.borderColor=i.primary;});
  const img=$('.topbar-brand img'); if(img) img.src=i.crest || 'lab/futbolcontrol-logo.svg';
}

function setupDashboard(){
  const root=createSection('fc-inicio','Inicio','Resumen deportivo y accesos rápidos'); addNav('fc-inicio','Inicio');
  root.innerHTML='<div id="fc-dashboard"></div>'; renderDashboard();
}
function renderDashboard(){
  const root=$('#fc-dashboard'); if(!root)return;
  const activeObj=state.objectives.filter(x=>!['Consolidado'].includes(x.status));
  const next=MATCHES.find(m=>m.status==='planned'); const last=MATCHES.find(m=>m.status==='finished'); const lastPost=state.postMatches.at(-1);
  root.innerHTML=`<div class="fc-grid">
    <article class="fc-card"><span class="fc-muted">Plantilla</span><div class="fc-kpi">${PLAYERS.length}</div><p>${PLAYERS.filter(p=>p.rating!==null).length} con valoración reciente · escala 1–5</p></article>
    <article class="fc-card"><span class="fc-muted">Próximo partido</span><h3>${esc(next.opponent)}</h3><p>${formatDate(next.date)} · ${esc(next.date.slice(11,16))} · ${esc(next.venue)}</p><span class="fc-tag">${esc(next.type)}</span></article>
    <article class="fc-card"><span class="fc-muted">Último partido</span><h3>${esc(last.opponent)}</h3><div class="fc-match-score">${last.gf}-${last.ga}</div><p>${formatDate(last.date)} · ${esc(last.type)}</p></article>
    <article class="fc-card"><span class="fc-muted">Objetivos individuales activos</span><div class="fc-kpi">${activeObj.length}</div><p>${new Set(activeObj.map(x=>x.playerId)).size} jugadores con seguimiento</p></article>
  </div>
  <div class="fc-two" style="margin-top:14px"><article class="panel"><h3>Prioridades actuales</h3>${lastPost?lastPost.problems.map((p,i)=>`<div class="fc-row"><div><strong>${i+1}. ${esc(p)}</strong><div class="fc-muted">${esc(PROBLEMS[p]?.principle||'')}</div></div></div>`).join(''):'<div class="fc-empty">Todavía no hay un postpartido guardado. Al registrar uno aparecerán aquí sus 1–3 prioridades.</div>'}</article><article class="panel"><h3>Jugadores a revisar</h3>${activeObj.length?activeObj.slice(0,5).map(o=>`<div class="fc-row"><div><strong>${esc(playerName(o.playerId))}</strong><div class="fc-muted">${esc(o.principle)} · ${esc(o.status)}</div></div><span class="fc-tag ${o.priority==='Alta'?'warn':''}">${esc(o.priority)}</span></div>`).join(''):'<div class="fc-empty">Añade objetivos en Desarrollo individual.</div>'}</article></div>`;
}

